package javax.microedition.lcdui;public class List extends Screen implements Choice {public static final Command SELECT_COMMAND=new Command("Select",Command.OK,0);private Command select=SELECT_COMMAND;private java.util.Vector strings=new java.util.Vector(),images=new java.util.Vector();private int selected,policy,type;public List(String title,int type){setTitle(title);this.type=type;}public List(String title,int type,String[]s,Image[]im){this(title,type);for(int i=0;i<s.length;i++)append(s[i],im==null?null:im[i]);}public int size(){return strings.size();}public String getString(int i){return (String)strings.elementAt(i);}public Image getImage(int i){return (Image)images.elementAt(i);}public int append(String s,Image im){strings.addElement(s);images.addElement(im);repaint();return size()-1;}public void insert(int i,String s,Image im){strings.insertElementAt(s,i);images.insertElementAt(im,i);repaint();}public void delete(int i){strings.removeElementAt(i);images.removeElementAt(i);selected=Math.max(0,Math.min(selected,size()-1));repaint();}public void deleteAll(){strings.removeAllElements();images.removeAllElements();selected=0;repaint();}public void set(int i,String s,Image im){strings.setElementAt(s,i);images.setElementAt(im,i);repaint();}public boolean isSelected(int i){return i==selected;}public int getSelectedIndex(){return size()==0?-1:selected;}public int getSelectedFlags(boolean[]f){for(int i=0;i<f.length;i++)f[i]=i<size()&&i==selected;return size()>0?1:0;}public void setSelectedIndex(int i,boolean b){if(i<0||i>=size())throw new IndexOutOfBoundsException();if(b)selected=i;repaint();}public void setSelectedFlags(boolean[]f){for(int i=0;i<Math.min(f.length,size());i++)if(f[i]){selected=i;break;}repaint();}public void setFitPolicy(int p){policy=p;}public int getFitPolicy(){return policy;}public void setFont(int i,Font f){}public Font getFont(int i){return Font.getDefaultFont();}public void setSelectCommand(Command c){select=c;}protected void keyPressed(int k){int a=getGameAction(k);if(size()>0){if(a==UP)selected=(selected+size()-1)%size();if(a==DOWN)selected=(selected+1)%size();}if(a==FIRE&&listener!=null&&select!=null)listener.commandAction(select,this);repaint();}protected void paint(Graphics g){g.setColor(0x122638);g.fillRect(0,0,getWidth(),getHeight());g.setColor(0xffffff);g.drawString(getTitle()==null?"":getTitle(),8,8,20);int start=Math.max(0,selected-(getHeight()/18-3));for(int i=start;i<size()&&i<start+getHeight()/18-2;i++){int y=32+(i-start)*18;if(i==selected){g.setColor(0x326681);g.fillRect(4,y-2,getWidth()-8,17);}g.setColor(0xffffff);g.drawString(getString(i),8,y,20);}}}
